import React, { useState } from "react";
import { motion } from "framer-motion";
import Stall from "./components/stall"; // Import the 3D Stall component

const WebApp = () => {
    const [darkMode, setDarkMode] = useState(false);

    const services = [
        { title: "Floor Planning", desc: "Strategic space management for maximum flow.", icon: "📐" },
        { title: "Vendor Sourcing", desc: "Connecting you with top-tier booth builders.", icon: "🤝" },
        { title: "Digital Integration", desc: "Hybrid event solutions and custom event apps.", icon: "🌐" },
    ];

    return (
        <div className={`${darkMode ? "bg-gray-900 text-white" : "bg-gray-50 text-gray-900"} min-h-screen transition-colors duration-500 font-sans`}>

            {/* --- Navigation --- */}
            <nav className={`fixed w-full z- px-8 py-6 flex justify-between items-center bg-white shadow-sm`}>
                <h1 className="text-2xl font-bold tracking-tight text-blue-600">VANTAGE EXHIBITS</h1>
                <div className="flex items-center gap-6">
                    <div className="space-x-6 hidden md:block text-gray-600 mr-4">
                        <a href="#services" className="hover:text-blue-600 transition">Services</a>
                        <a href="#portfolio" className="hover:text-blue-600 transition">Portfolio</a>
                    </div>
                    <button
                        onClick={() => setDarkMode(!darkMode)}
                        className="p-2 rounded-full bg-gray-100 hover:bg-gray-200 transition"
                    >
                        {darkMode ? "☀️" : "🌙"}
                    </button>
                    <button className="bg-blue-600 text-white px-5 py-2 rounded-full hover:bg-blue-700 transition">
                        Contact Us
                    </button>
                </div>
            </nav>

            {/* --- 3D Stall Preview (Top Slot) --- */}
            <div className="relative w-full h-[500px] overflow-hidden pt-20">
                <Stall />
            </div>

            {/* --- Original Blue Gradient Header --- */}
            <header className="py-20 px-8 text-center bg-gradient-to-r from-blue-900 to-indigo-800 text-white">
                <motion.div
                    initial={{ y: 30, opacity: 0 }}
                    whileInView={{ y: 0, opacity: 1 }}
                    viewport={{ once: true }}
                >
                    <h2 className="text-5xl font-extrabold mb-4">We Bring Your Vision to Life</h2>
                    <p className="text-xl opacity-90 max-w-2xl mx-auto">
                        Global leaders in trade show management, bespoke booth design, and large-scale corporate exhibitions.
                    </p>
                </motion.div>
            </header>

            {/* --- Services Section --- */}
            <section id="services" className="py-20 px-8 max-w-7xl mx-auto">
                <h3 className="text-3xl font-bold mb-12 text-center underline decoration-blue-500 underline-offset-8">Our Expertise</h3>
                <div className="grid md:grid-cols-3 gap-8">
                    {services.map((service, index) => (
                        <motion.div
                            key={index}
                            whileHover={{ y: -10 }}
                            className={`p-10 rounded-xl border ${darkMode ? "bg-gray-800 border-gray-700" : "bg-white border-gray-100"} shadow-sm hover:shadow-xl transition-all`}
                        >
                            <div className="w-12 h-12 bg-blue-100 rounded-lg mb-6 flex items-center justify-center text-blue-600 text-2xl">
                                {service.icon}
                            </div>
                            <h4 className="text-2xl font-bold mb-3">{service.title}</h4>
                            <p className="opacity-70 leading-relaxed">{service.desc}</p>
                        </motion.div>
                    ))}
                </div>
            </section>

            {/* --- Stats Section --- */}
            <section className={`py-16 ${darkMode ? "bg-gray-800" : "bg-blue-600"} text-white text-center`}>
                <div className="grid md:grid-cols-3 gap-10 max-w-5xl mx-auto">
                    <div>
                        <div className="text-5xl font-black">500+</div>
                        <div className="text-blue-200 mt-2">Events Managed</div>
                    </div>
                    <div>
                        <div className="text-5xl font-black">12M+</div>
                        <div className="text-blue-200 mt-2">Attendees Yearly</div>
                    </div>
                    <div>
                        <div className="text-5xl font-black">Global</div>
                        <div className="text-blue-200 mt-2">24 Country Reach</div>
                    </div>
                </div>
            </section>

            {/* --- Footer --- */}
            <footer className="py-12 text-center border-t border-gray-200 text-gray-500 bg-white">
                <p>© 2026 VANTAGE EXHIBITS. ALL RIGHTS RESERVED.</p>
            </footer>
        </div>
    );
};

export default WebApp;
